// LSP: a subtype must keep the parent's promises.
class BadBird { void fly() { System.out.println("Sparrow flies"); } }
class BadPenguin extends BadBird {
    // Breaks the promise "every BadBird can fly"
    @Override void fly() { throw new UnsupportedOperationException("cannot fly"); }
}
// Fix: only birds that really fly promise fly()
interface Bird { String move(); }
class Sparrow implements Bird { public String move() { return "Sparrow flies"; } }
class Penguin implements Bird { public String move() { return "Penguin walks"; } }

public class Main {
    public static void main(String[] args) {
        System.out.println("Bad design:");
        BadBird[] bad = { new BadBird(), new BadPenguin() };
        for (BadBird b : bad) {
            try { b.fly(); }
            catch (UnsupportedOperationException e) {
                System.out.println("Penguin.fly() threw: " + e.getMessage()); // client code broke
            }
        }
        System.out.println("Good design:");
        Bird[] good = { new Sparrow(), new Penguin() };
        for (Bird b : good) System.out.println(b.move()); // works for every subtype
    }
}

