// SRP: one class per actor, so one actor's change cannot alter another's result.
class SharedEmployee {              // BAD: payroll (finance) and report (HR) share one helper
    static int hours(int raw, boolean hrDropsLunch) { return raw - (hrDropsLunch ? 2 : 0); }
    static int pay(int raw, boolean rule) { return hours(raw, rule) * 50; }
    static int report(int raw, boolean rule) { return hours(raw, rule); }
}
class Payroll { static int pay(int raw) { return raw * 50; } }                 // finance owns this
class HrReport { static int report(int raw, boolean rule) { return raw - (rule ? 2 : 0); } } // HR owns this

public class Main {
    public static void main(String[] args) {
        int raw = 40;
        System.out.println("Raw hours: " + raw + ", rate 50");
        System.out.println("Shared helper, HR rule off: report=" + SharedEmployee.report(raw, false) + " pay=" + SharedEmployee.pay(raw, false));
        System.out.println("Shared helper, HR rule on:  report=" + SharedEmployee.report(raw, true) + " pay=" + SharedEmployee.pay(raw, true));
        // HR's change silently reduced pay. Split classes avoid that:
        System.out.println("Split classes, HR rule on:  report=" + HrReport.report(raw, true) + " pay=" + Payroll.pay(raw));
    }
}

