import java.util.*;
// OCP: a new payment method is a new class plus one wiring line; Checkout never changes.
interface PaymentMethod { String code(); int charge(int amount); }
class Card implements PaymentMethod {
    public String code() { return "card"; }
    public int charge(int a) { return a + a * 2 / 100; }   // 2% fee
}
class Upi implements PaymentMethod {
    public String code() { return "upi"; }
    public int charge(int a) { return a; }                 // no fee
}
class Wallet implements PaymentMethod {                    // added later: nothing else edited
    public String code() { return "wallet"; }
    public int charge(int a) { return a + a / 100; }       // 1% fee
}
class Checkout {
    private final Map<String, PaymentMethod> methods = new LinkedHashMap<>();
    Checkout(List<PaymentMethod> list) { for (PaymentMethod m : list) methods.put(m.code(), m); }
    int pay(String code, int amount) { return methods.get(code).charge(amount); }
    Set<String> codes() { return methods.keySet(); }
}
public class Main {
    public static void main(String[] args) {
        // Composition root: the one wiring line to touch
        Checkout c = new Checkout(List.of(new Card(), new Upi(), new Wallet()));
        for (String code : c.codes()) System.out.println(code + " 200 -> " + c.pay(code, 200));
    }
}

