import java.util.*;
// LSP via a contract test: run the SAME check against every implementation.
interface Basket { void add(int item); int size(); }
class ListBasket implements Basket {
    private final List<Integer> items = new ArrayList<>();
    public void add(int item) { items.add(item); }
    public int size() { return items.size(); }
}
class ReadOnlyBasket implements Basket {
    public void add(int item) { throw new UnsupportedOperationException("add not supported"); } // breaks the contract
    public int size() { return 0; }
}
public class Main {
    // Contract: after add(x), size() grows by exactly 1
    static String check(String name, Basket b) {
        int before = b.size();
        try { b.add(7); }
        catch (RuntimeException e) { return name + " fails contract: " + e.getMessage(); }
        return b.size() == before + 1 ? name + " passes contract" : name + " fails contract: size wrong";
    }
    public static void main(String[] args) {
        System.out.println(check("ListBasket", new ListBasket()));
        System.out.println(check("ReadOnlyBasket", new ReadOnlyBasket()));
    }
}

