// Square/Rectangle: mutable setters break LSP; immutable shapes have no promise to break.
class MutRect {
    int w, h;
    void setWidth(int x) { w = x; }
    void setHeight(int x) { h = x; }
    int area() { return w * h; }
}
class MutSquare extends MutRect {                  // keeps width == height, surprising the client
    @Override void setWidth(int x) { w = x; h = x; }
    @Override void setHeight(int x) { w = x; h = x; }
}
interface Shape { int area(); }
class Rect implements Shape {
    final int w, h;
    Rect(int w, int h) { this.w = w; this.h = h; }
    Rect withWidth(int x) { return new Rect(x, h); }   // returns a new object, no mutation
    public int area() { return w * h; }
}
class Sq implements Shape {
    final int side;
    Sq(int s) { side = s; }
    public int area() { return side * side; }
}
public class Main {
    static int clientArea(MutRect r) { r.setWidth(5); r.setHeight(4); return r.area(); } // expects 20
    public static void main(String[] args) {
        System.out.println("Mutable Square: expected area 20, got " + clientArea(new MutSquare()));
        Shape[] shapes = { new Rect(1, 4).withWidth(5), new Sq(4) };
        System.out.println("Immutable: rectangle 5x4 area=" + shapes[0].area() + ", square 4x4 area=" + shapes[1].area());
    }
}

