class MutRect {
    protected int w, h;
    public virtual void SetWidth(int x) { w = x; }
    public virtual void SetHeight(int x) { h = x; }
    public int Area() { return w * h; }
}
class MutSquare : MutRect {  // keeps width == height, surprising the client
    public override void SetWidth(int x) { w = x; h = x; }
    public override void SetHeight(int x) { w = x; h = x; }
}
interface IShape { int Area(); }
class Rect : IShape {
    readonly int w, h;
    public Rect(int w, int h) { this.w = w; this.h = h; }
    public Rect WithWidth(int x) { return new Rect(x, h); }  // returns a new object, no mutation
    public int Area() { return w * h; }
}
class Sq : IShape {
    readonly int side;
    public Sq(int s) { side = s; }
    public int Area() { return side * side; }
}
class Program {
    static int ClientArea(MutRect r) { r.SetWidth(5); r.SetHeight(4); return r.Area(); }  // expects 20
    static void Main() {
        Console.WriteLine("Mutable Square: expected area 20, got " + ClientArea(new MutSquare()));
        IShape[] shapes = { new Rect(1, 4).WithWidth(5), new Sq(4) };
        Console.WriteLine("Immutable: rectangle 5x4 area=" + shapes[0].Area() + ", square 4x4 area=" + shapes[1].Area());
    }
}

