// Decorator adds retries around a payment adapter without touching the adapter or the caller.
interface PaymentPort { void pay(int amount); }
class FlakyGateway implements PaymentPort {              // fails on its first two calls
    private int calls = 0;
    public void pay(int amount) {
        calls++;
        if (calls < 3) { System.out.println("attempt " + calls + " failed"); throw new RuntimeException("timeout"); }
        System.out.println("attempt " + calls + " ok");
    }
}
class RetryingPayment implements PaymentPort {
    private final PaymentPort inner; private final int max;
    RetryingPayment(PaymentPort inner, int max) { this.inner = inner; this.max = max; }
